#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <wmmintrin.h>
#include <emmintrin.h>
#include <tmmintrin.h>
#include <smmintrin.h>

// AES-128 key schedule
static void aes128_key_expand(__m128i *rk, const uint8_t *key) {
    rk[0] = _mm_loadu_si128((const __m128i*)key);
    __m128i t = rk[0];
    #define EXPAND(i, rcon) do { \
        __m128i tmp = _mm_aeskeygenassist_si128(t, rcon); \
        tmp = _mm_shuffle_epi32(tmp, 0xff); \
        t = _mm_xor_si128(t, _mm_slli_si128(t, 4)); \
        t = _mm_xor_si128(t, _mm_slli_si128(t, 4)); \
        t = _mm_xor_si128(t, _mm_slli_si128(t, 4)); \
        t = _mm_xor_si128(t, tmp); \
        rk[i] = t; \
    } while(0)
    EXPAND(1, 0x01); EXPAND(2, 0x02); EXPAND(3, 0x04); EXPAND(4, 0x08);
    EXPAND(5, 0x10); EXPAND(6, 0x20); EXPAND(7, 0x40); EXPAND(8, 0x80);
    EXPAND(9, 0x1b); EXPAND(10, 0x36);
}

// encrypt one block
static inline __m128i aes128_enc(__m128i b, const __m128i *rk) {
    b = _mm_xor_si128(b, rk[0]);
    b = _mm_aesenc_si128(b, rk[1]);
    b = _mm_aesenc_si128(b, rk[2]);
    b = _mm_aesenc_si128(b, rk[3]);
    b = _mm_aesenc_si128(b, rk[4]);
    b = _mm_aesenc_si128(b, rk[5]);
    b = _mm_aesenc_si128(b, rk[6]);
    b = _mm_aesenc_si128(b, rk[7]);
    b = _mm_aesenc_si128(b, rk[8]);
    b = _mm_aesenc_si128(b, rk[9]);
    b = _mm_aesenclast_si128(b, rk[10]);
    return b;
}

// 4-way parallel CTR (just encryption throughput, no GHASH)
static void aes_ctr_4x(const __m128i *rk, const uint8_t *in, uint8_t *out, size_t nblocks, uint64_t ctr_start) {
    // nonce is 0 for this microbench; counter in low 32? We'll just use counter as full block low 64
    for (size_t i = 0; i + 3 < nblocks; i += 4) {
        __m128i c0 = _mm_set_epi64x(0, (long long)(ctr_start + i));
        __m128i c1 = _mm_set_epi64x(0, (long long)(ctr_start + i + 1));
        __m128i c2 = _mm_set_epi64x(0, (long long)(ctr_start + i + 2));
        __m128i c3 = _mm_set_epi64x(0, (long long)(ctr_start + i + 3));
        c0 = _mm_xor_si128(c0, rk[0]); c1 = _mm_xor_si128(c1, rk[0]);
        c2 = _mm_xor_si128(c2, rk[0]); c3 = _mm_xor_si128(c3, rk[0]);
        for (int r = 1; r <= 9; r++) {
            c0 = _mm_aesenc_si128(c0, rk[r]);
            c1 = _mm_aesenc_si128(c1, rk[r]);
            c2 = _mm_aesenc_si128(c2, rk[r]);
            c3 = _mm_aesenc_si128(c3, rk[r]);
        }
        c0 = _mm_aesenclast_si128(c0, rk[10]);
        c1 = _mm_aesenclast_si128(c1, rk[10]);
        c2 = _mm_aesenclast_si128(c2, rk[10]);
        c3 = _mm_aesenclast_si128(c3, rk[10]);
        __m128i p0 = _mm_loadu_si128((const __m128i*)(in + i*16));
        __m128i p1 = _mm_loadu_si128((const __m128i*)(in + (i+1)*16));
        __m128i p2 = _mm_loadu_si128((const __m128i*)(in + (i+2)*16));
        __m128i p3 = _mm_loadu_si128((const __m128i*)(in + (i+3)*16));
        _mm_storeu_si128((__m128i*)(out + i*16), _mm_xor_si128(c0, p0));
        _mm_storeu_si128((__m128i*)(out + (i+1)*16), _mm_xor_si128(c1, p1));
        _mm_storeu_si128((__m128i*)(out + (i+2)*16), _mm_xor_si128(c2, p2));
        _mm_storeu_si128((__m128i*)(out + (i+3)*16), _mm_xor_si128(c3, p3));
    }
}

// 8-way
static void aes_ctr_8x(const __m128i *rk, const uint8_t *in, uint8_t *out, size_t nblocks) {
    size_t i = 0;
    for (; i + 7 < nblocks; i += 8) {
        __m128i c[8];
        for (int k = 0; k < 8; k++) c[k] = _mm_set_epi64x(0, (long long)(i + k));
        for (int k = 0; k < 8; k++) c[k] = _mm_xor_si128(c[k], rk[0]);
        for (int r = 1; r <= 9; r++)
            for (int k = 0; k < 8; k++) c[k] = _mm_aesenc_si128(c[k], rk[r]);
        for (int k = 0; k < 8; k++) c[k] = _mm_aesenclast_si128(c[k], rk[10]);
        for (int k = 0; k < 8; k++) {
            __m128i p = _mm_loadu_si128((const __m128i*)(in + (i+k)*16));
            _mm_storeu_si128((__m128i*)(out + (i+k)*16), _mm_xor_si128(c[k], p));
        }
    }
}

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    size_t nbytes = 60*1024*1024ULL; // 60MB
    size_t nblocks = nbytes / 16;
    uint8_t *in = aligned_alloc(64, nbytes);
    uint8_t *out = aligned_alloc(64, nbytes);
    memset(in, 1, nbytes);
    uint8_t key[16] = {0};
    __m128i rk[11];
    aes128_key_expand(rk, key);

    // warmup
    aes_ctr_8x(rk, in, out, nblocks);
    double t0 = now();
    int reps = 5;
    for (int r = 0; r < reps; r++) aes_ctr_8x(rk, in, out, nblocks);
    double t1 = now();
    double gbps = (double)nbytes * reps / (t1 - t0) / 1e9;
    printf("8x CTR: %.2f GB/s (%.3f s/iter)\n", gbps, (t1-t0)/reps);

    t0 = now();
    for (int r = 0; r < reps; r++) aes_ctr_4x(rk, in, out, nblocks, 0);
    t1 = now();
    gbps = (double)nbytes * reps / (t1 - t0) / 1e9;
    printf("4x CTR: %.2f GB/s (%.3f s/iter)\n", gbps, (t1-t0)/reps);

    // prevent DCE
    volatile uint8_t sink = out[0] ^ out[nbytes-1];
    (void)sink;
    return 0;
}
