} Worker;

static void *worker(void *arg) {
    Worker *w = arg;
    int seen = 0;
    while (1) {
        pthread_mutex_lock(&w->mtx);
        while (w->job_id == seen && !w->stop) pthread_cond_wait(&w->cv, &w->mtx);
