// Microbench: PCLMUL GHASH vs AES-CTR to see relative cost
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <wmmintrin.h>
#include <emmintrin.h>
#include <tmmintrin.h>
#include <smmintrin.h>

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

// reflected-less schoolbook carryless multiply of two 128-bit values, reduced mod x^128+x^7+x^2+x+1
// Using Intel's recommended 4-PCLMUL reduction (Gueron). Operates on bit-reflected inputs.
static inline __m128i clmul_reduce(__m128i a, __m128i b) {
    __m128i t1 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i t2 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i t3 = _mm_clmulepi64_si128(a, b, 0x01);
    __m128i t4 = _mm_clmulepi64_si128(a, b, 0x10);
    __m128i t = _mm_xor_si128(t3, t4);
    __m128i lo = _mm_xor_si128(t1, _mm_slli_si128(t, 8));
    __m128i hi = _mm_xor_si128(t2, _mm_srli_si128(t, 8));
    // reduction
    __m128i p = _mm_set_epi32(0, 0, 0, 0x00000087); // reflected poly? actually for reflected GHASH the reduction constant differs
    // We'll just do the multiply cost; reduction cost similar. Use Intel reduction for non-reflected:
    __m128i r = _mm_clmulepi64_si128(lo, p, 0x00);
    // fold
    lo = _mm_xor_si128(lo, _mm_slli_si128(r, 8));
    r = _mm_clmulepi64_si128(lo, p, 0x01); // not exact, just similar instruction mix
    hi = _mm_xor_si128(hi, r);
    hi = _mm_xor_si128(hi, lo);
    return hi;
}

int main() {
    size_t nbytes = 60ULL*1024*1024;
    size_t nblocks = nbytes/16;
    uint8_t *in = aligned_alloc(64, nbytes);
    memset(in, 1, nbytes);
    __m128i H = _mm_set_epi64x(0x123456789abcdef0LL, 0x0fedcba987654321LL);
    __m128i acc = _mm_setzero_si128();
    // warmup
    for (size_t i = 0; i < nblocks; i++) {
        __m128i x = _mm_loadu_si128((const __m128i*)(in + i*16));
        acc = clmul_reduce(_mm_xor_si128(acc, x), H);
    }
    double t0 = now();
    int reps = 3;
    for (int r = 0; r < reps; r++) {
        acc = _mm_setzero_si128();
        for (size_t i = 0; i < nblocks; i++) {
            __m128i x = _mm_loadu_si128((const __m128i*)(in + i*16));
            acc = clmul_reduce(_mm_xor_si128(acc, x), H);
        }
    }
    double t1 = now();
    printf("1x GHASH: %.2f GB/s (%.4f s) sink=%d\n", (double)nbytes*reps/(t1-t0)/1e9, (t1-t0)/reps, (int)_mm_cvtsi128_si32(acc));

    // 4-parallel GHASH (Horner with H^4): process 4 blocks, each multiplied by precomputed powers — approximate cost with 4 independent clmuls per block-group
    __m128i H1=H, H2=clmul_reduce(H,H), H3=clmul_reduce(H2,H), H4=clmul_reduce(H3,H);
    t0 = now();
    for (int r = 0; r < reps; r++) {
        __m128i a0=_mm_setzero_si128(), a1=_mm_setzero_si128(), a2=_mm_setzero_si128(), a3=_mm_setzero_si128();
        for (size_t i = 0; i+3 < nblocks; i += 4) {
            __m128i x0 = _mm_loadu_si128((const __m128i*)(in + (i)*16));
            __m128i x1 = _mm_loadu_si128((const __m128i*)(in + (i+1)*16));
            __m128i x2 = _mm_loadu_si128((const __m128i*)(in + (i+2)*16));
            __m128i x3 = _mm_loadu_si128((const __m128i*)(in + (i+3)*16));
            a0 = clmul_reduce(_mm_xor_si128(a0, x0), H4);
            a1 = clmul_reduce(_mm_xor_si128(a1, x1), H4);
            a2 = clmul_reduce(_mm_xor_si128(a2, x2), H4);
            a3 = clmul_reduce(_mm_xor_si128(a3, x3), H4);
        }
        acc = _mm_xor_si128(_mm_xor_si128(a0,a1), _mm_xor_si128(a2,a3));
    }
    t1 = now();
    printf("4x GHASH: %.2f GB/s (%.4f s) sink=%d\n", (double)nbytes*reps/(t1-t0)/1e9, (t1-t0)/reps, (int)_mm_cvtsi128_si32(acc));
    return 0;
}
