def reflect64(x):
    r = 0
    for i in range(64):
        if (x >> i) & 1:
            r |= 1 << (63 - i)
    return r

def clmul(a, b):
    r = 0
    for i in range(64):
        if (b >> i) & 1:
            r ^= a << i
    return r

def gfmul_reflected(a_be, b_be):
    # a_be, b_be are big-endian integers (GCM convention)
    a = int.from_bytes(a_be.to_bytes(16,'big'), 'little')
    b = int.from_bytes(b_be.to_bytes(16,'big'), 'little')
    # bit-reverse each byte? NO. byte swap only maps big-endian to little-endian byte order,
    # but PCLMUL interprets bits little-endian within bytes. The standard "reflected" GHASH
    # reverses ALL 128 bits. Let's compute with full bit reversal.
    def brev128(x):
        r = 0
        for i in range(128):
            if (x >> i) & 1: r |= 1 << (127-i)
        return r
    ar = brev128(a_be); br = brev128(b_be)
    # 256-bit carryless product
    prod = 0
    for i in range(128):
        if (br >> i) & 1:
            prod ^= ar << i
    # now reduce mod reflected poly: x^128 + x^7 + x^2 + x + 1, but in reflected domain the
    # poly is applied at the TOP. Let's instead just do the non-reflected reduction on the
    # bit-reversed product? Easier: compute product of reflected operands then reduce with
    # the reflected algorithm and compare to known.
    return prod

a = int("66e94bd4ef8a2c3b884cfa59ca342b2e", 16)
b = int("0388dace60b6a392f328c2b971b2fe78", 16)
prod = gfmul_reflected(a, b)
print("256-bit product of bit-reversed operands:")
print(prod.to_bytes(32,'little').hex())
print(prod.to_bytes(32,'big').hex())
