        if (ai < aad_len) {
            uint8_t last[16] = {0};
            memcpy(last, aad+ai, aad_len-ai);
            acc = gfmul(_mm_xor_si128(acc, reflect(_mm_loadu_si128((const __m128i*)last))), H);
        }
    }

    uint32_t ctr = 2;
    size_t i = 0;
    while (i + 16 <= len) {
        uint8_t cb[16];
        memcpy(cb, nonce, 12);
        cb[12] = ctr >> 24; cb[13] = ctr >> 16; cb[14] = ctr >> 8; cb[15] = ctr;
        ctr++;
        __m128i y = _mm_xor_si128(aes128(_mm_loadu_si128((const __m128i*)cb), rk),
                                  _mm_loadu_si128((const __m128i*)(pt+i)));
        _mm_storeu_si128((__m128i*)(ct+i), y);
        acc = gfmul(_mm_xor_si128(acc, reflect(y)), H);
        i += 16;
    }
    if (i < len) {
        uint8_t cb[16];
        memcpy(cb, nonce, 12);
        cb[12] = ctr >> 24; cb[13] = ctr >> 16; cb[14] = ctr >> 8; cb[15] = ctr;
        uint8_t kb[16];
        _mm_storeu_si128((__m128i*)kb, aes128(_mm_loadu_si128((const __m128i*)cb), rk));
        uint8_t pb[16] = {0};
        size_t rem = len - i;
        for (size_t k = 0; k < rem; k++) { ct[i+k] = pt[i+k] ^ kb[k]; pb[k] = ct[i+k]; }
        acc = gfmul(_mm_xor_si128(acc, reflect(_mm_loadu_si128((const __m128i*)pb))), H);
    }

    uint8_t lb[16] = {0};
    uint64_t ab = aad_len * 8, cb2 = len * 8;
    for (int k = 0; k < 8; k++) lb[k] = ab >> (56-8*k);
    for (int k = 0; k < 8; k++) lb[8+k] = cb2 >> (56-8*k);
    acc = gfmul(_mm_xor_si128(acc, reflect(_mm_loadu_si128((const __m128i*)lb))), H);

    _mm_storeu_si128((__m128i*)tag, _mm_xor_si128(reflect(acc), EK_J0));
}

static void hex(const char *n, const uint8_t *b, int l){printf("%s ",n); for(int i=0;i<l;i++) printf("%02x",b[i]); printf("\n");}

int main(){
    uint8_t key[16]={0}, nonce[12]={0}, pt[16]={0}, ct[16], tag[16];
    gcm128_encrypt(key, nonce, pt, ct, 16, NULL, 0, tag);
    hex("ct ", ct, 16); hex("tag", tag, 16);
    uint8_t aad[16]={0};
    gcm128_encrypt(key, nonce, pt, ct, 16, aad, 16, tag);
    hex("ct2 ", ct, 16); hex("tag2", tag, 16);
    uint8_t pt5[5]={1,2,3,4,5}, ct5[5];
    gcm128_encrypt(key, nonce, pt5, ct5, 5, aad, 7, tag);
    hex("ct5 ", ct5, 5); hex("tag5", tag, 16);
