    return _mm_set_epi64x((long long)r1, (long long)r0);
}

/* Build counter block: nonce(12) || big-endian counter. ctr fits in 32 bits. */
static inline __m128i ctr_block(uint32_t n0, uint32_t n1, uint32_t n2, uint32_t ctr) {
    /* nonce bytes are fixed; construct with byte swaps */
    uint32_t c = __builtin_bswap32(ctr);
    return _mm_set_epi32(c, n2, n1, n0);
}

void gcm128_encrypt(const uint8_t key[16], const uint8_t nonce[12],
                    const uint8_t *pt, uint8_t *ct, size_t len,
                    const uint8_t *aad, size_t aad_len, uint8_t tag[16]) {
    __m128i rk[11];
    aes128_expand(rk, key);
    __m128i H = reflect(aes128(_mm_setzero_si128(), rk));

    uint32_t n0, n1, n2;
    memcpy(&n0, nonce, 4); memcpy(&n1, nonce+4, 4); memcpy(&n2, nonce+8, 4);

    __m128i EK_J0 = aes128(ctr_block(n0, n1, n2, 1), rk);
    __m128i acc = _mm_setzero_si128();

    size_t ai = 0;
    if (aad && aad_len) {
        while (ai + 16 <= aad_len) {
            acc = gfmul(_mm_xor_si128(acc, reflect(_mm_loadu_si128((const __m128i*)(aad+ai)))), H);
            ai += 16;
        }
        if (ai < aad_len) {
            uint8_t last[16] = {0};
            memcpy(last, aad+ai, aad_len-ai);
            acc = gfmul(_mm_xor_si128(acc, reflect(_mm_loadu_si128((const __m128i*)last))), H);
        }
    }

    /* precompute H^1..H^8 for 8-way aggregation */
    __m128i Hp[9];
    Hp[1] = H;
    for (int k = 2; k <= 8; k++) Hp[k] = gfmul(Hp[k-1], H);

    size_t nblocks = len >> 4;
    size_t i = 0;
    uint32_t ctr = 2;

    while (i + 8 <= nblocks) {
        __m128i c0 = ctr_block(n0,n1,n2, ctr);
        __m128i c1 = ctr_block(n0,n1,n2, ctr+1);
        __m128i c2 = ctr_block(n0,n1,n2, ctr+2);
        __m128i c3 = ctr_block(n0,n1,n2, ctr+3);
        __m128i c4 = ctr_block(n0,n1,n2, ctr+4);
        __m128i c5 = ctr_block(n0,n1,n2, ctr+5);
        __m128i c6 = ctr_block(n0,n1,n2, ctr+6);
        __m128i c7 = ctr_block(n0,n1,n2, ctr+7);
        ctr += 8;
        c0=_mm_xor_si128(c0,rk[0]); c1=_mm_xor_si128(c1,rk[0]);
        c2=_mm_xor_si128(c2,rk[0]); c3=_mm_xor_si128(c3,rk[0]);
        c4=_mm_xor_si128(c4,rk[0]); c5=_mm_xor_si128(c5,rk[0]);
        c6=_mm_xor_si128(c6,rk[0]); c7=_mm_xor_si128(c7,rk[0]);
        #define R(r) \
            c0=_mm_aesenc_si128(c0,rk[r]); c1=_mm_aesenc_si128(c1,rk[r]); \
            c2=_mm_aesenc_si128(c2,rk[r]); c3=_mm_aesenc_si128(c3,rk[r]); \
            c4=_mm_aesenc_si128(c4,rk[r]); c5=_mm_aesenc_si128(c5,rk[r]); \
            c6=_mm_aesenc_si128(c6,rk[r]); c7=_mm_aesenc_si128(c7,rk[r]);
        R(1) R(2) R(3) R(4) R(5) R(6) R(7) R(8) R(9)
        #undef R
        c0=_mm_aesenclast_si128(c0,rk[10]); c1=_mm_aesenclast_si128(c1,rk[10]);
        c2=_mm_aesenclast_si128(c2,rk[10]); c3=_mm_aesenclast_si128(c3,rk[10]);
        c4=_mm_aesenclast_si128(c4,rk[10]); c5=_mm_aesenclast_si128(c5,rk[10]);
        c6=_mm_aesenclast_si128(c6,rk[10]); c7=_mm_aesenclast_si128(c7,rk[10]);

        const uint8_t *pi = pt + i*16; uint8_t *po = ct + i*16;
        __m128i y0=_mm_xor_si128(c0, _mm_loadu_si128((const __m128i*)pi));
        __m128i y1=_mm_xor_si128(c1, _mm_loadu_si128((const __m128i*)(pi+16)));
        __m128i y2=_mm_xor_si128(c2, _mm_loadu_si128((const __m128i*)(pi+32)));
        __m128i y3=_mm_xor_si128(c3, _mm_loadu_si128((const __m128i*)(pi+48)));
        __m128i y4=_mm_xor_si128(c4, _mm_loadu_si128((const __m128i*)(pi+64)));
        __m128i y5=_mm_xor_si128(c5, _mm_loadu_si128((const __m128i*)(pi+80)));
        __m128i y6=_mm_xor_si128(c6, _mm_loadu_si128((const __m128i*)(pi+96)));
        __m128i y7=_mm_xor_si128(c7, _mm_loadu_si128((const __m128i*)(pi+112)));
        _mm_storeu_si128((__m128i*)po, y0);
        _mm_storeu_si128((__m128i*)(po+16), y1);
        _mm_storeu_si128((__m128i*)(po+32), y2);
        _mm_storeu_si128((__m128i*)(po+48), y3);
        _mm_storeu_si128((__m128i*)(po+64), y4);
        _mm_storeu_si128((__m128i*)(po+80), y5);
        _mm_storeu_si128((__m128i*)(po+96), y6);
        _mm_storeu_si128((__m128i*)(po+112), y7);

        /* aggregated GHASH: acc = (acc + y0)*H^8 + y1*H^7 + ... + y7*H^1 */
        __m128i x0 = reflect(y0), x1 = reflect(y1), x2 = reflect(y2), x3 = reflect(y3);
        __m128i x4 = reflect(y4), x5 = reflect(y5), x6 = reflect(y6), x7 = reflect(y7);
        __m128i m0 = gfmul(_mm_xor_si128(acc, x0), Hp[8]);
        __m128i m1 = gfmul(x1, Hp[7]);
        __m128i m2 = gfmul(x2, Hp[6]);
        __m128i m3 = gfmul(x3, Hp[5]);
        __m128i m4 = gfmul(x4, Hp[4]);
        __m128i m5 = gfmul(x5, Hp[3]);
        __m128i m6 = gfmul(x6, Hp[2]);
        __m128i m7 = gfmul(x7, Hp[1]);
        acc = _mm_xor_si128(_mm_xor_si128(_mm_xor_si128(m0,m1), _mm_xor_si128(m2,m3)),
                            _mm_xor_si128(_mm_xor_si128(m4,m5), _mm_xor_si128(m6,m7)));
        i += 8;
    }
    /* tail blocks */
    for (; i < nblocks; i++) {
        __m128i y = _mm_xor_si128(aes128(ctr_block(n0,n1,n2, ctr), rk),
                                  _mm_loadu_si128((const __m128i*)(pt+i*16)));
        ctr++;
        _mm_storeu_si128((__m128i*)(ct+i*16), y);
        acc = gfmul(_mm_xor_si128(acc, reflect(y)), H);
    }
    size_t done = nblocks*16;
    if (done < len) {
        uint8_t kb[16];
        _mm_storeu_si128((__m128i*)kb, aes128(ctr_block(n0,n1,n2, ctr), rk));
        uint8_t pb[16] = {0};
        for (size_t k = 0; k < len-done; k++) { ct[done+k] = pt[done+k] ^ kb[k]; pb[k] = ct[done+k]; }
        acc = gfmul(_mm_xor_si128(acc, reflect(_mm_loadu_si128((const __m128i*)pb))), H);
    }

    uint8_t lb[16] = {0};
    uint64_t ab = aad_len*8, cb2 = len*8;
    for (int k = 0; k < 8; k++) lb[k] = ab >> (56-8*k);
    for (int k = 0; k < 8; k++) lb[8+k] = cb2 >> (56-8*k);
    acc = gfmul(_mm_xor_si128(acc, reflect(_mm_loadu_si128((const __m128i*)lb))), H);
    _mm_storeu_si128((__m128i*)tag, _mm_xor_si128(reflect(acc), EK_J0));
}

int main() {
    /* correctness vs a few random cases is checked externally; here just throughput + one vector */
    uint8_t key[16]={0}, nonce[12]={0};
    size_t len = 64;
    uint8_t pt[64]={0}, ct[64], tag[16];
    gcm128_encrypt(key, nonce, pt, ct, len, NULL, 0, tag);
    printf("tag64: "); for(int i=0;i<16;i++) printf("%02x", tag[i]); printf("\n");

    size_t big = 60ULL*1024*1024;
    uint8_t *P = aligned_alloc(64, big), *C = aligned_alloc(64, big);
    memset(P, 1, big);
    uint8_t tg[16];
    gcm128_encrypt(key, nonce, P, C, big, NULL, 0, tg);
    double t0 = now(); int reps=3;
    for (int r=0;r<reps;r++) gcm128_encrypt(key, nonce, P, C, big, NULL, 0, tg);
    double t1 = now();
    printf("throughput: %.2f GB/s (%.4f s) sink=%02x\n", (double)big*reps/(t1-t0)/1e9, (t1-t0)/reps, tg[0]);
    return 0;
}
