static inline __m128i reduce(__m128i lo, __m128i hi) {
    /* shift hi left by 0,1,2,7 and xor into (lo, overflow) */
    __m128i ov = _mm_srli_epi64(hi, 57);          /* top = hi >> (64-7); only low 7 bits matter, sits in low qword */
    __m128i hi_sl7 = _mm_or_si128(_mm_slli_epi64(hi, 7), _mm_srli_epi64(_mm_slli_si128(hi, 8), 57));
    __m128i hi_sl2 = _mm_or_si128(_mm_slli_epi64(hi, 2), _mm_srli_epi64(_mm_slli_si128(hi, 8), 62));
    __m128i hi_sl1 = _mm_or_si128(_mm_slli_epi64(hi, 1), _mm_srli_epi64(_mm_slli_si128(hi, 8), 63));
    __m128i r = _mm_xor_si128(_mm_xor_si128(lo, hi), _mm_xor_si128(hi_sl1, _mm_xor_si128(hi_sl2, hi_sl7)));
    /* overflow byte: ov holds (hi >> 57) in its LOW qword only? hi>>57 on both qwords.
       We only want the high qword's overflow. Isolate it. */
    __m128i ov_hi = _mm_srli_si128(_mm_srli_epi64(hi, 57), 8); /* high qword overflow in low qword, rest 0 */
    /* but shifts 1 and 2 also overflow from the high qword: */
    __m128i ov1 = _mm_srli_si128(_mm_srli_epi64(hi, 63), 8);
    __m128i ov2 = _mm_srli_si128(_mm_srli_epi64(hi, 62), 8);
