    /* fold ova (only low ~7 bits) by x^0+x^1+x^2+x^7 */
    __m128i f = _mm_xor_si128(ova, _mm_slli_epi64(ova, 1));
    f = _mm_xor_si128(f, _mm_slli_epi64(ova, 2));
    f = _mm_xor_si128(f, _mm_slli_epi64(ova, 7));
    return _mm_xor_si128(r, f);
