}
static inline __m128i ref_gf(__m128i a, __m128i b) {
    __m128i z0=_mm_clmulepi64_si128(a,b,0x00), z2=_mm_clmulepi64_si128(a,b,0x11);
    __m128i z1=_mm_xor_si128(_mm_clmulepi64_si128(a,b,0x01),_mm_clmulepi64_si128(a,b,0x10));
    uint64_t p0=(uint64_t)_mm_cvtsi128_si64(z0);
