    uint64_t p2=(uint64_t)_mm_cvtsi128_si64(z2)^(uint64_t)_mm_extract_epi64(z1,1);
    uint64_t p3=(uint64_t)_mm_extract_epi64(z2,1);
    uint64_t h0=p2,h1=p3,r0=p0,r1=p1,ov=0; int sh[4]={0,1,2,7};
    for(int i=0;i<4;i++){int s=sh[i]; uint64_t low,mid,top; if(s==0){low=h0;mid=h1;top=0;} else {low=h0<<s;mid=(h1<<s)|(h0>>(64-s));top=h1>>(64-s);} r0^=low;r1^=mid;ov^=top;}
    r0^=ov^(ov<<1)^(ov<<2)^(ov<<7); return _mm_set_epi64x((long long)r1,(long long)r0);
}
