    __m128i t2 = _mm_clmulepi64_si128(lo2, poly, 0x01); /* low64(lo2) * high64(poly) */
    return _mm_xor_si128(hi2, _mm_xor_si128(t2, _mm_srli_si128(lo2, 8)));
