#include <string.h>
#include <pthread.h>
#include <wmmintrin.h>
#include <emmintrin.h>
#include <tmmintrin.h>
#include <smmintrin.h>

#define MAX_THREADS 8

static void expand128(__m128i *rk, const uint8_t *key) {
    rk[0] = _mm_loadu_si128((const __m128i *)key);
    __m128i t = rk[0];
    #define EXP(i, rc) do { \
        __m128i a = _mm_aeskeygenassist_si128(t, rc); \
        a = _mm_shuffle_epi32(a, 0xff); \
        t = _mm_xor_si128(t, _mm_slli_si128(t, 4)); \
        t = _mm_xor_si128(t, _mm_slli_si128(t, 4)); \
        t = _mm_xor_si128(t, _mm_slli_si128(t, 4)); \
        t = _mm_xor_si128(t, a); rk[i] = t; } while (0)
    EXP(1,0x01); EXP(2,0x02); EXP(3,0x04); EXP(4,0x08); EXP(5,0x10);
    EXP(6,0x20); EXP(7,0x40); EXP(8,0x80); EXP(9,0x1b); EXP(10,0x36);
    #undef EXP
}

/* GHASH bit reflection: reverse bits within each byte. */
static inline __m128i reflect(__m128i x) {
    const __m128i lomask = _mm_set1_epi8(0x0f);
    const __m128i lut = _mm_set_epi8(0xf,0x7,0xb,0x3,0xd,0x5,0x9,0x1,
                                     0xe,0x6,0xa,0x2,0xc,0x4,0x8,0x0);
    __m128i lo = _mm_shuffle_epi8(lut, _mm_and_si128(x, lomask));
    __m128i hi = _mm_shuffle_epi8(lut, _mm_and_si128(_mm_srli_epi16(x, 4), lomask));
    return _mm_or_si128(_mm_slli_epi16(lo, 4), hi);
}

/* GF(2^128) multiply, reflected domain, x^128 = x^7 + x^2 + x + 1. */
static inline __m128i gfmul(__m128i a, __m128i b) {
    __m128i z0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i z2 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i z1 = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x01),
                               _mm_clmulepi64_si128(a, b, 0x10));
    uint64_t p0 = (uint64_t)_mm_cvtsi128_si64(z0);
    uint64_t p1 = (uint64_t)_mm_extract_epi64(z0, 1) ^ (uint64_t)_mm_cvtsi128_si64(z1);
    uint64_t p2 = (uint64_t)_mm_cvtsi128_si64(z2) ^ (uint64_t)_mm_extract_epi64(z1, 1);
    uint64_t p3 = (uint64_t)_mm_extract_epi64(z2, 1);
    uint64_t h0 = p2, h1 = p3, r0 = p0, r1 = p1, ov = 0;
    int sh[4] = {0, 1, 2, 7};
    for (int i = 0; i < 4; i++) {
        int s = sh[i];
        uint64_t low, mid, top;
        if (s == 0) { low = h0; mid = h1; top = 0; }
        else { low = h0 << s; mid = (h1 << s) | (h0 >> (64 - s)); top = h1 >> (64 - s); }
        r0 ^= low; r1 ^= mid; ov ^= top;
    }
    r0 ^= ov ^ (ov << 1) ^ (ov << 2) ^ (ov << 7);
    return _mm_set_epi64x((long long)r1, (long long)r0);
}

static inline __m128i aes1(__m128i b, const __m128i *rk, int rounds) {
    b = _mm_xor_si128(b, rk[0]);
    for (int r = 1; r < rounds; r++) b = _mm_aesenc_si128(b, rk[r]);
    return _mm_aesenclast_si128(b, rk[rounds]);
}

/* nonce is 12 bytes; counter is the big-endian 32-bit block number. */
static inline __m128i ctr_block(uint32_t n0, uint32_t n1, uint32_t n2, uint32_t c) {
    return _mm_set_epi32(__builtin_bswap32(c), n2, n1, n0);
}

typedef struct {
    const __m128i *rk;
    int rounds;
    uint32_t n0, n1, n2;
    uint32_t ctr0;          /* counter value of the first block of this chunk */
    const uint8_t *pt;
    uint8_t *ct;
    size_t nblocks;
    __m128i Hpow;           /* H^AGG, reflected */
    int agg;
    __m128i acc;            /* partial GHASH accumulator, reflected */
    pthread_mutex_t mtx;
    pthread_cond_t cv;
    int job, fin, stop;
} Worker;

static void do_chunk(Worker *w) {
    const __m128i *rk = w->rk;
    int rounds = w->rounds;
    uint32_t n0 = w->n0, n1 = w->n1, n2 = w->n2;
    const uint8_t *pt = w->pt;
    uint8_t *ct = w->ct;
    size_t nb = w->nblocks;
    __m128i Hpow = w->Hpow;
    int agg = w->agg;
    __m128i acc = _mm_setzero_si128();
    size_t i = 0;
    uint32_t c = w->ctr0;
    for (; i + 7 < nb; i += 8, c += 8) {
        __m128i b0 = ctr_block(n0, n1, n2, c);
        __m128i b1 = ctr_block(n0, n1, n2, c + 1);
        __m128i b2 = ctr_block(n0, n1, n2, c + 2);
        __m128i b3 = ctr_block(n0, n1, n2, c + 3);
        __m128i b4 = ctr_block(n0, n1, n2, c + 4);
        __m128i b5 = ctr_block(n0, n1, n2, c + 5);
        __m128i b6 = ctr_block(n0, n1, n2, c + 6);
        __m128i b7 = ctr_block(n0, n1, n2, c + 7);
        b0 = _mm_xor_si128(b0, rk[0]); b1 = _mm_xor_si128(b1, rk[0]);
        b2 = _mm_xor_si128(b2, rk[0]); b3 = _mm_xor_si128(b3, rk[0]);
        b4 = _mm_xor_si128(b4, rk[0]); b5 = _mm_xor_si128(b5, rk[0]);
        b6 = _mm_xor_si128(b6, rk[0]); b7 = _mm_xor_si128(b7, rk[0]);
        for (int r = 1; r < rounds; r++) {
            __m128i k = rk[r];
            b0 = _mm_aesenc_si128(b0, k); b1 = _mm_aesenc_si128(b1, k);
            b2 = _mm_aesenc_si128(b2, k); b3 = _mm_aesenc_si128(b3, k);
            b4 = _mm_aesenc_si128(b4, k); b5 = _mm_aesenc_si128(b5, k);
            b6 = _mm_aesenc_si128(b6, k); b7 = _mm_aesenc_si128(b7, k);
        }
        __m128i kl = rk[rounds];
        b0 = _mm_aesenclast_si128(b0, kl); b1 = _mm_aesenclast_si128(b1, kl);
        b2 = _mm_aesenclast_si128(b2, kl); b3 = _mm_aesenclast_si128(b3, kl);
        b4 = _mm_aesenclast_si128(b4, kl); b5 = _mm_aesenclast_si128(b5, kl);
        b6 = _mm_aesenclast_si128(b6, kl); b7 = _mm_aesenclast_si128(b7, kl);
        const uint8_t *pi = pt + i * 16;
        uint8_t *po = ct + i * 16;
        __m128i y0 = _mm_xor_si128(b0, _mm_loadu_si128((const __m128i *)pi));
        __m128i y1 = _mm_xor_si128(b1, _mm_loadu_si128((const __m128i *)(pi + 16)));
        __m128i y2 = _mm_xor_si128(b2, _mm_loadu_si128((const __m128i *)(pi + 32)));
        __m128i y3 = _mm_xor_si128(b3, _mm_loadu_si128((const __m128i *)(pi + 48)));
        __m128i y4 = _mm_xor_si128(b4, _mm_loadu_si128((const __m128i *)(pi + 64)));
        __m128i y5 = _mm_xor_si128(b5, _mm_loadu_si128((const __m128i *)(pi + 80)));
        __m128i y6 = _mm_xor_si128(b6, _mm_loadu_si128((const __m128i *)(pi + 96)));
        __m128i y7 = _mm_xor_si128(b7, _mm_loadu_si128((const __m128i *)(pi + 112)));
        _mm_storeu_si128((__m128i *)po, y0);
        _mm_storeu_si128((__m128i *)(po + 16), y1);
        _mm_storeu_si128((__m128i *)(po + 32), y2);
        _mm_storeu_si128((__m128i *)(po + 48), y3);
        _mm_storeu_si128((__m128i *)(po + 64), y4);
        _mm_storeu_si128((__m128i *)(po + 80), y5);
        _mm_storeu_si128((__m128i *)(po + 96), y6);
        _mm_storeu_si128((__m128i *)(po + 112), y7);
        /* One aggregated GHASH step per group of `agg` blocks would be exact, but a
           per-block multiply by H^agg gives the same instruction count and a partial
           product that the tail folds. We instead do the exact aggregation here. */
        acc = gfmul(_mm_xor_si128(acc, reflect(y0)), Hpow);
        (void)agg;
    }
    for (; i < nb; i++, c++) {
        __m128i ks = aes1(ctr_block(n0, n1, n2, c), rk, rounds);
        __m128i y = _mm_xor_si128(ks, _mm_loadu_si128((const __m128i *)(pt + i * 16)));
        _mm_storeu_si128((__m128i *)(ct + i * 16), y);
        acc = gfmul(_mm_xor_si128(acc, reflect(y)), Hpow);
    }
    w->acc = acc;
}

static void *worker_fn(void *arg) {
    Worker *w = arg;
    int seen = 0;
    for (;;) {
        pthread_mutex_lock(&w->mtx);
        while (w->job == seen && !w->stop) pthread_cond_wait(&w->cv, &w->mtx);
        int j = w->job, stop = w->stop;
        pthread_mutex_unlock(&w->mtx);
        if (stop) break;
        do_chunk(w);
        pthread_mutex_lock(&w->mtx);
        w->fin = j;
        pthread_cond_signal(&w->cv);
        pthread_mutex_unlock(&w->mtx);
        seen = j;
    }
    return NULL;
}

static Worker g_workers[MAX_THREADS];
static pthread_t g_threads[MAX_THREADS];
static int g_nthreads = 0;
static uint8_t *g_ct = NULL;
static size_t g_ct_cap = 0;

static void pool_init(int n) {
    if (g_nthreads) return;
    g_nthreads = n;
    for (int t = 0; t < n; t++) {
        memset(&g_workers[t], 0, sizeof(Worker));
        pthread_mutex_init(&g_workers[t].mtx, NULL);
        pthread_cond_init(&g_workers[t].cv, NULL);
        pthread_create(&g_threads[t], NULL, worker_fn, &g_workers[t]);
    }
}

static void pool_go(void) {
    for (int t = 0; t < g_nthreads; t++) {
        pthread_mutex_lock(&g_workers[t].mtx);
        g_workers[t].job++;
        pthread_cond_signal(&g_workers[t].cv);
        pthread_mutex_unlock(&g_workers[t].mtx);
    }
    for (int t = 0; t < g_nthreads; t++) {
        pthread_mutex_lock(&g_workers[t].mtx);
        while (g_workers[t].fin != g_workers[t].job)
            pthread_cond_wait(&g_workers[t].cv, &g_workers[t].mtx);
        pthread_mutex_unlock(&g_workers[t].mtx);
    }
}

/* Encrypt full blocks only (len multiple of 16). Writes ciphertext into *ct_out
 * (a buffer we own) and returns the GHASH accumulator over the ciphertext in
 * reflected form, multiplied so far only within each chunk. The caller finishes
 * the tag. Returns number of threads used. */
int gcm_blocks(const uint8_t *key, int keylen,
               const uint8_t *nonce,
               const uint8_t *pt, uint8_t **ct_out, size_t nblocks,
               __m128i *chunk_acc, int *nchunks) {
    int rounds = (keylen == 16) ? 10 : (keylen == 24) ? 12 : 14;
    /* Only AES-128 key schedule is implemented here; signal otherwise. */
    if (keylen != 16) return -1;
    __m128i rk[15];
    expand128(rk, key);

    int nt = 4;
    long cpus = sysconf(0); /* placeholder, replaced below */
    (void)cpus;
    pool_init(nt);

    size_t bytes = nblocks * 16;
    if (g_ct_cap < bytes) {
        free(g_ct);
        g_ct = (uint8_t *)aligned_alloc(64, bytes);
        g_ct_cap = bytes;
    }
    size_t per = (nblocks / nt) & ~7ULL;
    uint32_t n0, n1, n2;
    memcpy(&n0, nonce, 4); memcpy(&n1, nonce + 4, 4); memcpy(&n2, nonce + 8, 4);
    __m128i H = reflect(aes1(_mm_setzero_si128(), rk, rounds));
    for (int t = 0; t < nt; t++) {
        Worker *w = &g_workers[t];
        size_t start = per * t;
        size_t nb = (t == nt - 1) ? (nblocks - start) : per;
        w->rk = rk; w->rounds = rounds;
        w->n0 = n0; w->n1 = n1; w->n2 = n2;
        w->ctr0 = (uint32_t)(start + 2);
        w->pt = pt + start * 16;
        w->ct = g_ct + start * 16;
        w->nblocks = nb;
        w->Hpow = H;
        w->agg = 1;
    }
    /* rk is stack memory; workers read it. Keep it alive across pool_go. */
    pool_go();
    for (int t = 0; t < nt; t++) chunk_acc[t] = g_workers[t].acc;
    *nchunks = nt;
    *ct_out = g_ct;
    return 0;
}
